#!/usr/bin/env python3
"""
Write the known MCP tool list the skill-tools rule checks against.

Reads a mcp-plugins checkout: the homelab plugin's own tools from
docs/TOOLS.md and the third-party server tools from .ci/third_party_tools.txt.

Usage:
    python3 gen_mcp_tools.py [--plugin DIR] [--out FILE]
"""

from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

HEADER = (
    "# Known MCP tool names of the homelab plugin, one per line, for the\n"
    "# repo-standard skill-tools rule. Generated by `make mcp-tools` from a\n"
    "# mcp-plugins checkout (docs/TOOLS.md, .ci/third_party_tools.txt); do not\n"
    "# edit by hand.\n"
)


def collect(plugin: Path) -> list[str]:
    tools = set(re.findall(r"^### `([a-z_]+)`", (plugin / "docs/TOOLS.md").read_text(), re.M))
    for line in (plugin / ".ci/third_party_tools.txt").read_text().splitlines():
        line = line.strip()
        if line and not line.startswith("#"):
            tools.add(line)
    return sorted(tools)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.strip().splitlines()[0])
    parser.add_argument("--plugin", default=Path("../mcp-plugins"), type=Path)
    parser.add_argument("--out", default=Path(".ci/config/mcp-tools.txt"), type=Path)
    args = parser.parse_args(argv)
    tools = collect(args.plugin)
    args.out.write_text(HEADER + "".join(f"{t}\n" for t in tools))
    print(f"{args.out}: {len(tools)} tools")
    return 0


if __name__ == "__main__":
    sys.exit(main())
